package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.NumberIsTooLargeException;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for the OpenMapRealMatrix constructor.
 */
public class OpenMapRealMatrix_OpenMapRealMatrix_TriageGen2Test {











    @Test
    public void testConstructorInitializationState() {
        int rows = 3;
        int cols = 3;
        OpenMapRealMatrix matrix = new OpenMapRealMatrix(rows, cols);

        // Verify that entries are initialized to 0.0 by default (via getEntry)
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                assertEquals("Initial entry should be 0.0", 0.0, matrix.getEntry(i, j), 1e-15);
            }
        }
    }


}

package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.NumberIsTooLargeException;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for the OpenMapRealMatrix constructor.
 */
public class OpenMapRealMatrix_OpenMapRealMatrix_TriageGen2Test {













    @Test
    public void testConstructorWithCopyConstructor() {
        int rows = 2;
        int cols = 2;
        OpenMapRealMatrix original = new OpenMapRealMatrix(rows, cols);
        original.setEntry(0, 0, 1.5);
        original.setEntry(1, 1, 2.5);

        OpenMapRealMatrix copy = new OpenMapRealMatrix(original);

        assertNotNull("Copied matrix should not be null", copy);
        assertEquals("Rows should match original", rows, copy.getRowDimension());
        assertEquals("Cols should match original", cols, copy.getColumnDimension());
        assertEquals("Entry (0,0) should match", 1.5, copy.getEntry(0, 0), 1e-15);
        assertEquals("Entry (1,1) should match", 2.5, copy.getEntry(1, 1), 1e-15);

        // Ensure it's a deep copy (modifying copy shouldn't affect original)
        copy.setEntry(0, 0, 9.9);
        assertNotEquals("Copy should be independent", 1.5, original.getEntry(0, 0), 1e-15);
    }
}
